-- HOLIDAYS · Halloween · Halloween · 10–12 · beginners
do $mig$
declare
  v_course uuid; v_unit uuid; v_lesson uuid;
  v_media text := 'https://classroom.wowteach.ru/media/';
begin
  select id into v_course from classroom_courses where slug = 'holidays';
  if v_course is null then raise exception 'course holidays not found'; end if;

  select id into v_unit from classroom_units
   where course_id = v_course and title = 'Halloween' limit 1;
  if v_unit is null then
    insert into classroom_units (course_id, title, sort_order)
    values (v_course, 'Halloween', 1) returning id into v_unit;
  end if;

  select id into v_lesson from classroom_lessons
   where unit_id = v_unit and title = 'Halloween · 10–12 · beginners' limit 1;
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, summary, sort_order, is_published, pass_threshold, kind)
    values (v_unit, 'Halloween · 10–12 · beginners', 'Урок-игра для 10–12 лет, начинающие', 3, false, 60, 'lesson')
    returning id into v_lesson;
  else
    update classroom_lessons set summary = 'Урок-игра для 10–12 лет, начинающие', sort_order = 3,
           is_published = false, pass_threshold = 60, kind = 'lesson'
     where id = v_lesson;
  end if;

  insert into classroom_blocks (lesson_id, type, payload, sort_order) values
    -- блок 1 (sort_order 0) · кнопка: урок в новой вкладке
    (v_lesson, 'text', replace($blk${"html": "<div style=\"text-align:center;padding:22px 16px;background:linear-gradient(180deg,#fff7ec,#ffe9cc);border-radius:18px;border:2px solid #f3d3a3\">\n<h2 style=\"margin:0 0 6px;color:#8a3c08\">🎃 Halloween · 10–12 · beginners</h2>\n<p style=\"margin:0 0 16px;color:#6b4a2a\">Интерактивный урок. Откройте его и демонстрируйте в Zoom <b>эту вкладку</b>, а не весь экран.</p>\n<p style=\"margin:0\"><a href=\"https://classroom.wowteach.ru/lessons/halloween/10-12_beginners.html\" style=\"display:inline-block;padding:14px 38px;border-radius:99px;background:#c0612b;color:#fff;font-weight:700;font-size:18px;text-decoration:none\">▶ Открыть урок на весь экран</a></p>\n<p style=\"margin:14px 0 0;color:#8a6a4a;font-size:13px\">План урока — кнопка 📋 вверху справа внутри урока (откроется отдельным окном) или ниже на этой странице.<br>Нужен интернет: картинки и музыка загружаются с сервера.</p></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 0),
    -- блок 2 (sort_order 1) · превью урока
    (v_lesson, 'embed', replace($blk${"url": "https://classroom.wowteach.ru/lessons/halloween/10-12_beginners.html"}$blk$, '@@MEDIA@@', v_media)::jsonb, 1),
    -- блок 3 (sort_order 2) · план — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>План урока</h3><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>Длительность:</b> 40 мин. &nbsp; <b>Мотивация:</b> детектив — ученик ищет улики, получает эликсир правды, допрашивает подозреваемых и находит вора Золотой тыквы. Вор каждый раз случайный.</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>📖 История (расскажите в начале, по-русски или простыми фразами):</b> В маленьком городке Spooky Town на главной площади стояла <b>Золотая тыква</b> — главное украшение праздника Хэллоуин. Вечером 30 октября, ровно в 9:15, она пропала! Утром 31-го об этом написали все газеты. Полиция не справляется, поэтому зовут лучшего детектива — <b>ученика</b>. Помогает ему кошка-сыщик <b>Inspector Whiskers</b>. Подозреваемых шестеро: ведьма Wanda, вампир Count Vlad, мумия Mumford, оборотень Wolfie, скелет Mr Bones и привидение Boo. За урок детектив соберёт пять улик, найдёт <b>эликсир правды</b> (кто его выпьет, не может соврать), проверит сумки, допросит подозреваемых и найдёт вора. <b>Вор каждый раз выбирается случайно</b> — даже учитель не знает его заранее.</div><div style=\"background:#fff3cd;border:3px solid #c0392b;border-radius:12px;padding:12px 16px;margin:10px 0;font-weight:700;color:#7a1f12\">⚠️ ЕСЛИ НЕ ХВАТАЕТ ВРЕМЕНИ — НАЖМИТЕ ЗНАЧОК 🗄 (EVIDENCE ROOM, ВВЕРХУ СПРАВА, РЯДОМ С 📋). ОН ЕСТЬ НА ВСЕХ СТРАНИЦАХ ДО ДОПРОСА. УЧЕНИК НАЖИМАЕТ НА УЛИКИ, КОТОРЫХ У НЕГО ЕЩЁ НЕТ, — И ВЫ СРАЗУ ПЕРЕХОДИТЕ К ДОПРОСУ. СТРЕЛКА ← ВЕРНЁТ НА СТРАНИЦУ, С КОТОРОЙ ВЫ ПРИШЛИ.</div><table style=\"width:100%;border-collapse:collapse;font-size:14px\"><tr><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Стр.</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Задание и инструкция</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Teacher's language</th><th style=\"background:#6e3510;color:#fff;padding:8px 10px;text-align:left\">Suggested answers / Students' answers</th></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">1</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Начало: площадь и Золотая тыква → газета (3 шага, Next).</b> На экране площадь Spooky Town, на постаменте — Золотая тыква (она мигает). Ученик пробует назвать её; Next / нажатие на тыкву — появляется слово <b>a golden pumpkin</b> и звучит. Next — тыква исчезает (тот же кадр, пустой постамент). Next — вылетает газета «WHERE IS THE GOLDEN PUMPKIN?». Расскажите историю (см. выше).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Look! What's this?\" \"It's a golden pumpkin. Repeat!\" \"Where is the pumpkin now?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"A pumpkin!\" \"A golden pumpkin!\" \"I don't know!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">2</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Halloween-слова (6 карточек):</b> a witch, a vampire, a mummy, a werewolf, a skeleton, a ghost — это и есть подозреваемые. Сначала только картинки. Ученик пробует назвать, нажатие показывает слово и <b>произносит его</b>. Next открывает следующую карточку. Повторить хором. <br><i>Остальные слова урока у начинающих подписаны прямо на экране</i> (фонарик, стрелки на карте, отличия, правда/ложь, улики на допросе) — заранее их учить не нужно.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Who is this?\" \"Is it a witch or a ghost?\" \"Repeat!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"A witch!\" \"A vampire!\" \"It's a ghost!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">3</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Подозреваемые.</b> Шесть карточек: портрет и имя. <b>Сначала ученик сам говорит, кто это</b> («She is a witch»), <b>потом нажимаем и проверяем</b> — открывается фраза. Next открывает следующую. <b>Вор каждый раз выбирается случайно</b> — заранее его не знает никто.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Who is this? Is she a witch?\" \"Say: She is a…\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Wanda. She is a witch.\" \"He is a vampire.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">4</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Фонарик (3 раунда).</b> Тёмная площадь, предметы спрятаны. Учитель водит фонарик мышкой (без мыши он бродит сам), ученик говорит, куда светить. Нашли — нажмите на предмет. Последний предмет — часы. Рядом с заданием — картинка того, что ищем. В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Find the lantern! Left or right? Up or down?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Left! Up! Here!\" \"A watch!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">5</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Свидетель (3 вопроса).</b> Сова Mrs Owl рассказывает, что видела. Учитель читает фразу, ученик выбирает картинку. <b>Подписей нет.</b> Перед первым раундом попросите ученика <b>показать руками tall и short</b>, потом выбрать силуэт. Нажмите на верный вариант. В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Show me tall! Show me short!\" \"Is the thief tall or short?\" \"What colour is the scarf?\" \"Where is the thief?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">(показывает руками) \"Tall!\" \"Red!\" \"The park!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">6</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Шифровка.</b> Записка из символов, внизу — алфавит-ключ. Ученик находит символ в ключе и называет букву, учитель нажимает на символ в записке — появляется буква. Послание: I LOVE CANDIES. В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What letter is this?\" \"Find the symbol in the key.\" \"What does the note say?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"I… L-O-V-E… I love candies!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">7</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Следы.</b> Карта городка. Пунктиром мигают следы следующего шага, ученик говорит направление: up / down / left / right. Учитель нажимает стрелку — кошка идёт. 5 шагов, в конце — старая башня. В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Where are the footprints? Up or down?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Left!\" \"Up!\" \"Right!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">8</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>До и после (6 отличий).</b> Площадь до кражи и после. Ученик называет отличия, учитель нажимает на них (на любой картинке). У найденного отличия появляется слово. В конце — карточка улики, она попадает в блокнот (слева). Next — дальше.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What's different?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"The pumpkin!\" \"The glasses!\" \"A cat!\" \"The lamp!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">9</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Правда или ложь (6 утверждений).</b> Проверяем, что запомнили. Ученик отвечает, учитель нажимает TRUE / FALSE: верная кнопка «вдавливается» с ✓, при ошибке — «Try again!». Награда — <b>эликсир правды</b> (карточка «Look! The truth elixir!»). <i>Объясните по-русски: кошка нашла волшебный эликсир — кто его выпьет, не сможет соврать. На допросе подозреваемые выпьют его и будут отвечать честно.</i></td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Is it true or false?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"True!\" \"False! The scarf is red.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">10</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Рентген сумок (все 6 подозреваемых).</b> У каждого своя сумка. Нажмите на сумку — сверху вниз проходит лазер, внутри видны тени предметов. Ученик угадывает предмет, учитель нажимает на тень — предмет проявляется. У двух случайных подозреваемых (но никогда не у вора) в сумке <b>билет в кино на 9:00</b> — это алиби, они получают штамп NOT GUILTY.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What's in the bag? Is it a key?\" \"Has she got a ticket?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"A key! A phone! A ticket!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">11</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Допрос. Решает ученик.</b> Подозреваемые пьют эликсир правды. <b>Сначала нажмите на улику</b> (слева) — появится вопрос. Ученик задаёт его, учитель <b>нажимает на подозреваемого</b> — тот отвечает. Справа — решение по выбранному подозреваемому: <b>NOT GUILTY</b> или <b>THE THIEF!</b> Нажимаете, когда ученик сам скажет и объяснит. Если решение неверное, программа не даст его принять. Передумал — нажмите на подозреваемого со штампом и <b>↩ Undo</b> (снимаются и штампы с рентгена).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Choose a clue. Ask Wanda!\" \"Is she the thief? Yes or no?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Have you got a watch?\" — \"Yes, I have. / No, I haven't.\" \"Wanda — not guilty!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">12</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Финал.</b> Вор в наручниках у полицейского участка, кошка с Золотой тыквой, «CASE CLOSED!». Сразу выскакивает окно <b>«What's your name, detective?»</b> — ученик вписывает имя, ✓ — имя появляется на значке. ✏️ Name — исправить, 💾 Save — скачать картинку. Справа кнопки <b>🏁 Finish</b> (сразу на финальный слайд) и <b>⭐ Extra</b> (дополнительные задания: bucket list, потом настольная игра).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Who is the thief?\" \"What's your name, detective?\" \"Well done!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It's Count Vlad!\" \"My name is…\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">13</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Бонус (если есть время): Halloween bucket list.</b> Нажатие на карточку — в список, нажатие в списке — убрать. Внизу можно дописать свой пункт. Внизу справа кнопки 🏁 Finish (на финальный слайд) и ⭐ Extra (настольная игра).</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"What do you want to do on Halloween?\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"I want to carve a pumpkin.\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">14</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Extra: настольная игра «Spooky Town».</b> Сюда ведёт кнопка ⭐ Extra на странице bucket list. Выберите фишки (1–5 игроков, можно вписать имена) → ▶ Play. Кубик — по очереди (Next тоже бросает). На клетках картинки — только 6 слов урока (witch, vampire, mummy, werewolf, skeleton, ghost): «Who is it?» — ученик называет. ⏩ +2, ⏪ −2, ⭐ — весёлое задание (Make a scary face! / Say BOO! / Fly like a bat!). Кто первым дошёл до башни 🏁 — победил. 🏁 Finish внизу справа — закончить урок в любой момент.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Who is it?\" \"Roll the dice!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"It's a witch!\" \"It's a werewolf!\"</td></tr><tr><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;font-weight:700;color:#c0392b;font-size:17px;text-align:center;width:44px\">15</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top\"><b>Finish.</b> «Great job, detective! Happy Halloween!» — конфетти, прощаемся.</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1a7a3a;font-style:italic;width:22%\">\"Great job! Happy Halloween! Bye!\"</td><td style=\"padding:8px 10px;border-bottom:1px solid #eee;vertical-align:top;color:#1f5fa8;font-style:italic;width:22%\">\"Happy Halloween!\"</td></tr></table><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🗂️ Лексика и грамматика:</b> <b>Новые слова:</b> witch, vampire, mummy, werewolf, skeleton, ghost. <b>С подсказками на экране:</b> watch, scarf, glasses, boots, candies, ticket, tall, short, park, cafe, church, cinema • Have you got…? Yes, I have / No, I haven't • Do you like…? Yes, I do / No, I don't • up, down, left, right • colours. <b>Только Present Simple и to be — без прошедшего времени.</b></div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0;font-size:13px;color:#777\"><b>Навигация:</b> ← → — назад / пропустить; Next загорается, когда задание выполнено, а в играх с раундами ведёт к следующему раунду (подсказывает ответ). Кружочки страниц вверху слева кликабельны. 🗄 — склад улик, 📋 — этот план, 🎵 — музыка.</div><div style=\"background:#fff;border:1px solid #e6e0f0;border-radius:12px;padding:12px 16px;margin:10px 0\"><b>🏠 Домашнее задание</b> — материал <b>«Halloween Homework · 10–12 · beginners»</b> на платформе: «Материалы» → «Задать ДЗ» → ученик → отметить. Только слова урока, 10–15 минут. Задания:<ol style=\"margin:6px 0 0 22px\"><li>Карточки со звуком</li><li>🎤 Повтори слова</li><li>Послушай и выбери картинку</li><li>Соедини слово и картинку</li><li>Собери слово из букв</li><li>🎤 Назови, что видишь на картинке</li></ol><div style=\"color:#777;font-size:13px;margin-top:4px\">Устные задания ученик записывает голосом — их вы слушаете и оцениваете в «Проверке ДЗ».</div></div>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 2),
    -- блок 4 (sort_order 3) · ДЗ — только преподавателю
    (v_lesson, 'text', replace($blk${"html": "<h3>Домашнее задание</h3><p>Материал <b>«Halloween Homework · 10–12 · beginners»</b> в этом же юните. «Материалы» → «Задать ДЗ» → ученик → отметить.</p>"}$blk$, '@@MEDIA@@', v_media)::jsonb, 3)
  on conflict (lesson_id, sort_order) do update
    set type = excluded.type, payload = excluded.payload;

  delete from classroom_blocks where lesson_id = v_lesson and sort_order >= 4;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 0;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 2;
  update classroom_blocks set audience = 'teacher' where lesson_id = v_lesson and sort_order = 3;
end
$mig$;
